import{_ as e,o as a,c as s,a0 as i}from"./chunks/framework.D4fUSYzX.js";const f=JSON.parse('{"title":"First Launch","description":"Start the control plane with the npx one-liner or from source; the first start downloads the binary and writes the config file.","frontmatter":{"title":"First Launch","description":"Start the control plane with the npx one-liner or from source; the first start downloads the binary and writes the config file."},"headers":[],"relativePath":"getting-started/first-launch.md","filePath":"getting-started/first-launch.md"}'),n={name:"getting-started/first-launch.md"};function o(r,t,l,h,c,d){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h1><p>Run either name; both start the same app:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mlsf</span></span></code></pre></div><p>The first start downloads the prebuilt binary for your machine and caches it under your data home, in a directory per target - <code>~/.local/share/my-little-software-factory/bin/&lt;target&gt;</code>, or <code>%LOCALAPPDATA%\\my-little-software-factory\\bin\\&lt;target&gt;</code> on Windows - so a second start finds the cache and skips the network. To drop the cache, delete the data-home directory: <code>rm -rf ~/.local/share/my-little-software-factory</code>.</p><p>With no config file, the start writes the <a href="./minimal-config.html#the-config-file">Default configuration</a> to <code>~/.config/my-little-software-factory/config.toml</code> and says so on the start lines, so you know where your config file lives and where to edit. A line that does not parse or does not validate stops the start with one readable error line.</p><p><code>factory --version</code> answers with the version the install carries, and <code>factory --config &lt;path&gt;</code> starts on the config file you name; both flags work before any config exists. An install you keep uses the same launcher: <code>npm install -g my-little-software-factory</code> puts a <code>factory</code> command on your <code>PATH</code>, and it runs the binary the way <code>npx</code> does.</p><h2 id="run-from-source" tabindex="-1">Run from source <a class="header-anchor" href="#run-from-source" aria-label="Permalink to &quot;Run from source&quot;">​</a></h2><p>To run the plane from source instead of the published binary:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/SeriousJul/my-little-software-factory</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>This runs the same app the binary runs, with no hot reload and no development config, and it reads the same config file the binary uses - <code>~/.config/my-little-software-factory/config.toml</code> - so your setup is identical to a binary install.</p><p>Next: <a href="./minimal-config.html">the minimal config</a>.</p>`,11)])])}const u=e(n,[["render",o]]);export{f as __pageData,u as default};
